import{_ as t,c as s,o as n,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"《橫渠易說》簡介","description":"橫渠易說 - 《橫渠易說》簡介","frontmatter":{"title":"《橫渠易說》簡介","description":"橫渠易說 - 《橫渠易說》簡介"},"headers":[],"relativePath":"classics/hengqu/001.md","filePath":"classics/hengqu/001.md"}'),l={name:"classics/hengqu/001.md"};function c(o,a,i,d,p,u){return n(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"《橫渠易說》簡介",tabindex:"-1"},[r("《橫渠易說》簡介 "),e("a",{class:"header-anchor",href:"#《橫渠易說》簡介","aria-label":"Permalink to “《橫渠易說》簡介”"},"​")],-1),e("p",null,"探索易學深邃，領略智慧之光。在這裡，我們不僅提供《橫渠易說》等經典著作的在線閱讀，更匯聚了周易八卦、易經六十四卦等豐富內容，滿足您對易學知識的全面需求。從周易全文的完整呈現，到易經講解的深入淺出，再到周易預測的神秘魅力，我們致力於為您打造一個全方位、多層次的易學學習平臺。無論您是初學者還是資深愛好者，都能在這裡找到屬於自己的智慧啟迪和心靈歸宿。張載的學術思想以《易經》為宗，以《中庸》為體，以孔孟為法，其學說強調了天人合一的哲學理念，並對後世的理學發展產生了深遠影響。",-1),e("p",null,"《橫渠易說》的主要內容形成於張載三十歲至五十歲之間，並在晚年有所增益和修訂。張載在書中不僅繼承了傳統的象數易學，更側重於義理的闡發，並根據自己的理論要求進行了創新。他提出了剛柔說、取象說、爻位說等易學理論，並對《周易》進行了深入的哲學詮釋。",-1),e("p",null,"《橫渠易說》的學術史意義重大，它不僅代表了張載思想的逐漸形成與成熟，而且對宋明理學以及後來的中國文化產生了深遠的影響。此書的校注版本由劉泉校注，對書中的疑難字詞、概念範疇等進行了註釋和分析，並附有張載的傳記、書目序跋、歷代評議等文獻作為附錄。",-1),e("p",null,"張載的《橫渠易說》也被認為是氣學《易》學的代表作，其哲學思想以“氣”為萬物之本，認為“天惟運動一氣，鼓萬物而生”。這本書體現了張載早年的學術觀點，儘管文字相對粗糙，但已經具備了唯物主義的基本觀點。",-1)])])}const f=t(l,[["render",c]]);export{_ as __pageData,f as default};
